<script setup lang="ts">
/**
 * Boolean (or indeterminate) choice (`design/components/checkbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/checkbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/checkbox'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/checkbox.module.css'

export type CheckedState = boolean | 'indeterminate'

export interface CheckboxProps {
  ariaDescribedby?: string
  ariaLabel?: string
  /**
   * The id of a label elsewhere on the page, such as `SettingsRow`'s one label for a whole row.
   */
  ariaLabelledby?: string
  ariaRequired?: boolean
  checked?: boolean | 'indeterminate'
  defaultChecked?: boolean | 'indeterminate'
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField.
   */
  invalid?: boolean
  /**
   * Visible inline label. Omit it only where the context labels the box, and then `aria-label`
   * is required.
   */
  label?: string
  name?: string
  value?: string
}

defineOptions({ name: 'Checkbox', inheritAttrs: false, controlKind: 'row-labelled' })

const props = withDefaults(defineProps<CheckboxProps>(), {
  ariaRequired: undefined,
  checked: undefined,
  defaultChecked: undefined,
  disabled: false,
  invalid: false,
})
const emit = defineEmits<{ checkedChange: [checked: CheckedState] }>()
const uid = useId()
const box = useTemplateRef<HTMLElement>('box')
const documentDirection = useDirection(() => box.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    checked: props.checked,
    defaultChecked: props.defaultChecked,
    disabled: props.disabled,
    invalid: props.invalid,
    required: props.ariaRequired,
    name: props.name,
    value: props.value,
    onCheckedChange: (details) => {
      emit('checkedChange', details.checked)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const dataState = computed(() =>
  api.value.indeterminate ? 'indeterminate' : api.value.checked ? 'checked' : 'unchecked',
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Checkbox',
    element: () => box.value,
    state: () => ({
      checked: api.value.indeterminate ? 'mixed' : api.value.checked,
      disabled: props.disabled,
    }),
    actions: {
      check: () => api.value.setChecked(true),
      uncheck: () => api.value.setChecked(false),
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <button
    v-if="label === undefined"
    ref="box"
    :class="styles.box"
    type="button"
    role="checkbox"
    :id="id"
    :aria-checked="api.indeterminate ? 'mixed' : api.checked"
    :disabled="disabled"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-required="ariaRequired"
    :aria-invalid="invalid ? true : undefined"
    :data-state="dataState"
    :data-disabled="disabled ? '' : undefined"
    :data-required="ariaRequired ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    data-member="checkbox"
    @click="api.toggleChecked()"
    @keydown="$event.key === 'Enter' && $event.preventDefault()"
  >
    <!-- indicator -->
    <span v-if="api.checked || api.indeterminate" :class="styles.indicator" :data-state="dataState">
      <Icon :name="api.indeterminate ? 'indeterminate' : 'confirm'" size="sm" />
    </span>
  </button>
  <label
    v-else
    :class="styles.row"
    :data-state="dataState"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-required="ariaRequired ? '' : undefined"
    data-member="checkbox"
  >
    <!-- box -->
    <button
      ref="box"
      :class="styles.box"
      type="button"
      role="checkbox"
      :id="id"
      :aria-checked="api.indeterminate ? 'mixed' : api.checked"
      :disabled="disabled"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      :aria-invalid="invalid ? true : undefined"
      :data-state="dataState"
      :data-disabled="disabled ? '' : undefined"
      :data-required="ariaRequired ? '' : undefined"
      :data-invalid="invalid ? '' : undefined"
      data-member="checkbox"
      @click="api.toggleChecked()"
      @keydown="$event.key === 'Enter' && $event.preventDefault()"
    >
      <!-- indicator -->
      <span
        v-if="api.checked || api.indeterminate"
        :class="styles.indicator"
        :data-state="dataState"
      >
        <Icon :name="api.indeterminate ? 'indeterminate' : 'confirm'" size="sm" />
      </span>
    </button>
    <!-- label -->
    <span :class="styles.label">
      {{ label }}
    </span>
  </label>
  <input
    v-if="name !== undefined && api.checked"
    type="hidden"
    :name="name"
    :value="value ?? 'on'"
  />
</template>
